from pathlib import Path
import base64,zlib,hashlib
payload=''''''
# Correct known transport slips without relaxing the decoded source checksum.
payload=payload.replace('ndm0357NTQ','ndm03187NTQ').replace('kLCcs9kgmo','kLCUa79kgmo').replace('PGmVVAl','PGmVAl')
source=zlib.decompress(base64.b64decode(payload,validate=True))
assert len(source)==13948
assert hashlib.sha256(source).hexdigest()=='95d13f9170c5f0c284b79de8d38ca89f7f02afd1d6e7857556bd37fa15599d9e'
Path('distribution').mkdir(exist_ok=True)
Path('distribution/task-choice-review-readable.py').write_bytes(source)
exec(compile(source,'task-choice-review-readable.py','exec'))
